/* Expanded original guides for CBSE language, social-science, commerce and computer-science studies. */
(function () {
  "use strict";
  const guide = (level, subject, chapter, intro, sections, points, workedExamples, commonMistakes, examFocus, recall, glossary) => ({
    level,subject,chapter,intro,sections,points,formulas:[],example:workedExamples.length?workedExamples[0].steps.join(" "):"Use the process outline, explain key terms in your own words and support claims with evidence.",
    workedExamples,commonMistakes,examFocus,recall,glossary,depth:"detailed",
    sourceNote:"Original study guidance, not an official answer key. Match chapter names, case studies, prescribed literature, formats and current syllabus to the CBSE subject/edition used at your school."
  });

  const g10History=guide("Class 10","Social Science","CBSE Class 10 History — Nationalism, Mass Movements and Historical Evidence",
    "A method-led guide for understanding nationalism, colonial rule, mass mobilisation, the global economy and the role of print/culture in historical change.",
    [
      {heading:"Explain historical change through causes and consequences",body:"History answers are strongest when they distinguish long-term conditions, immediate triggers, the people involved and the consequences. Avoid treating an event as the result of one cause when the evidence suggests several. A useful paragraph structure is claim → contextual evidence → explanation → consequence. Chronology is important, but the goal is not merely to list dates; explain why one event changed the options available to the next actors. When a question asks 'why', give causal links. When it asks 'how', describe the process and sequence. When it asks 'evaluate', weigh both achievement and limitation."},
      {heading:"Nationalism and collective identity",body:"Nationalism is not a single fixed idea: it can be connected to shared history, language, cultural symbols, territory, political rights or opposition to external rule. National identities are often built through flags, songs, images, commemorations, maps, public rituals and narratives of a common past. Such symbols can unite groups but can also exclude communities whose histories differ. In answers, distinguish the idea of a nation from a state and from a government. Explain who created a symbol, its intended meaning, which audience it addressed and how people responded."},
      {heading:"Colonial rule and mass politics",body:"Mass movements form through interaction between political leadership and local concerns. A national call can mean different things to peasants, workers, business groups, students and women because each group enters with its own grievances and expectations. Colonial policies, repression, taxation, restrictions and economic disruption can increase mobilisation. A careful answer connects local motives to national-level organisation, while noting that participation and outcomes are not uniform across every region or social group."},
      {heading:"Global links, industrialisation and print culture",body:"Historical change can be traced through flows of people, commodities, capital, technology and ideas. Global trade can expand markets while creating unequal dependence and new vulnerabilities. Industrialisation changes labour, production and family/community life, but does so unevenly. Print culture increases the circulation of ideas and public debate; access to printing, literacy, censorship and language shape who can participate. Explain both the new opportunities created and the social conflicts or exclusions that accompanied them."},
      {heading:"Using sources and building a 5-mark response",body:"A source-based question requires evidence from the excerpt or image, not an unrelated fact dump. Identify the source's author/time/audience where available, interpret its purpose and connect it to the relevant historical setting. A 5-mark response often benefits from five distinct but developed points, or several connected paragraphs, depending on the question. A point should include an explanation; repeating the question in different words does not create a separate mark. Do not invent quotations, page numbers or an exact statistic that you cannot verify."}
    ],
    ["Cause → event/process → consequence","Historical source: author/context/purpose/evidence/audience","Compare: similarity + difference + explanation","Evaluate: achievement + limitation + reasoned judgement"],
    [
      {title:"Plan a 'why' answer",steps:["Circle the command word and identify the time period.","Write two or three distinct causes rather than synonyms.","For each cause, explain the mechanism connecting it to the event.","End with a consequence or a sentence that directly answers the question."]},
      {title:"Analyse a source",steps:["Identify what the source says or depicts literally.","Place it in historical context using only relevant knowledge.","Explain whose perspective/purpose is visible and what might be omitted.","Support the conclusion with a detail from the source itself."]}
    ],
    ["Writing a chronology without explaining cause and effect.","Assuming every social group had the same reason for joining a movement.","Ignoring the source in a source-based question.","Making absolute claims about all regions or all communities without evidence."],
    ["Use precise names/dates only where relevant. Structure answers around causation, process, group interests, outcomes and evidence. Use the prescribed textbook's case studies and current syllabus to decide which movements/chapters are in scope."],
    ["How are a nation, state and government different?","Why can the same movement appeal to different groups for different reasons?","What does source context add to historical interpretation?"],
    ["Nationalism: political/cultural idea that a people form a nation or should have collective political agency.","Mass mobilisation: large-scale public participation in political action.","Primary source: evidence created in the period/event being studied."]);

  const g10Geography=guide("Class 10","Social Science","CBSE Class 10 Geography — Resources, Agriculture, Water, Minerals, Industry and Development",
    "Learn geography as a chain linking physical conditions, resource use, economic activity, spatial patterns and sustainability.",
    [
      {heading:"Resources and development planning",body:"A resource is not only a natural object; it becomes useful when people have the knowledge, technology, access and institutions needed to use it. Resources can be classified by origin, exhaustibility, ownership and development status. Unplanned exploitation may cause depletion, pollution, unequal access or ecological damage. Resource planning connects inventory, technology/infrastructure and institutional priorities. Sustainable development means meeting current needs while preserving future options, not simply stopping all use."},
      {heading:"Land, soil and water",body:"Land use varies with relief, climate, population, technology and economic incentives. Soil formation depends on parent material, climate, organisms, topography and time. Soil erosion removes fertile topsoil; conservation can use contour ploughing, terracing, shelter belts, strip cropping and vegetation cover according to local conditions. Water scarcity can result from seasonal variability, over-extraction, pollution or uneven distribution, not only low rainfall. Watershed management and rainwater harvesting are local strategies whose results depend on geology, community participation and maintenance."},
      {heading:"Agriculture and food security",body:"Cropping patterns reflect climate, soil, irrigation, seed availability, labour, markets, prices and policy. Distinguish crop seasons and examples using the prescribed course text. Intensive farming can increase yield but may create groundwater, soil or chemical-use pressures if poorly managed. Food security depends on availability, access, affordability and stability. A good answer connects farm practices to both productivity and environmental/economic outcomes."},
      {heading:"Minerals, energy and manufacturing",body:"Mineral deposits are spatially uneven, and extraction has environmental costs. Conventional energy sources can be reliable but contribute to emissions and depletion; renewables have different storage, transmission, material and land requirements. Manufacturing adds value and creates jobs, but can produce industrial pollution. Location factors include raw materials, labour, power, transport, capital, water, markets and government policy; relative importance varies by industry and technology."},
      {heading:"Map and data interpretation",body:"Map questions depend on correct symbols, locations and scale. First identify the state/region or physical feature, then use nearby rivers, coastlines, mountain ranges or boundaries as reference. For a graph/table, cite the data pattern, compare categories and explain the likely geography. Avoid overstating causation from correlation. For sustainability questions, propose measures that match the scale: household, farm, watershed, city or industry."}
    ],
    ["Resource planning: inventory → technology/infrastructure → implementation/institutions","Soil erosion control: vegetation, contouring, terracing, shelter belts where appropriate","Food security: availability + access + affordability + stability","Industry location: raw materials, energy, labour, water, transport, capital, markets"],
    [
      {title:"Write a resource-sustainability answer",steps:["Identify the resource and the pressure on it.","Explain the cause of the pressure with the relevant geography/economics link.","Describe two feasible conservation or management measures.","State the expected outcome and any condition needed for success."]},
      {title:"Interpret a map",steps:["Read the legend and scale before locating features.","Use a known anchor such as coast, state border or river.","Mark the requested point/region precisely.","Check the spelling and symbol convention requested by the question."]}
    ],
    ["Calling every resource renewable without specifying the time scale.","Treating water scarcity as caused only by low rainfall.","Listing conservation measures that do not fit the local setting.","Reading a graph without citing actual comparisons."],
    ["Connect every topic to location, physical conditions, human use, environmental effects and management. Practise the exact current map-work list in your prescribed CBSE syllabus."],
    ["What makes an object a resource?","List two causes of soil erosion and matching controls.","What are the four dimensions of food security?"],
    ["Resource planning: organised assessment and sustainable use of resources.","Watershed: land area draining to a common outlet.","Food security: reliable access to sufficient safe and nutritious food."]);

  const g10Civics=guide("Class 10","Social Science","CBSE Class 10 Civics — Power Sharing, Federalism, Parties and Democracy",
    "Understand political institutions through legitimacy, accountability, decentralisation, representation and the role of parties.",
    [
      {heading:"Power sharing and democracy",body:"Power sharing distributes authority among institutions, levels of government, social groups or political actors. It reduces the risk of a single group monopolising decisions and can make public policy more legitimate. Horizontal distribution separates institutions such as legislature, executive and judiciary; vertical distribution divides authority across central, state and local levels. Power sharing is not just a moral slogan: explain the institutional mechanism and the conflict it is designed to manage."},
      {heading:"Federalism and decentralisation",body:"A federal arrangement allocates powers between levels of government through constitutional rules. Federal design can protect regional diversity while preserving national coordination. Key features include specified jurisdictions, a written constitutional allocation, a process to resolve disputes and institutions that support each level's authority. Decentralisation moves certain decisions closer to local communities, but its effectiveness depends on funds, functionaries, legal authority, transparency and citizen participation."},
      {heading:"Political parties and elections",body:"Parties aggregate interests, select candidates, contest elections, form governments and organise opposition. They help voters choose among broad policy options but can face challenges such as concentration of power, dynastic succession, money influence and limited internal democracy. In evaluating a reform, describe the target problem, the rule/incentive it changes, likely benefits and possible unintended effects. Avoid assuming a single reform can solve every institutional weakness."},
      {heading:"Democracy: outcomes and accountability",body:"Democratic quality includes meaningful participation, accountability, responsiveness, rights, equality before law and peaceful change of government. Elections are necessary but not sufficient; citizens also need access to information, institutions that can check power and procedures to challenge unfair treatment. Democracies can be slow because negotiation takes time, but this can also improve legitimacy. Use a balanced answer distinguishing expected ideals from actual performance."},
      {heading:"Structured political-science answers",body:"Define the concept, explain the mechanism, give the prescribed textbook example, and connect it back to the question. For comparisons, use consistent dimensions such as distribution of power, source of authority, accountability and role of citizens. For case-based questions, extract the constitutional/administrative feature described in the case and apply it, rather than quoting a memorised definition unrelated to the scenario."}
    ],
    ["Horizontal sharing: institutions at the same level","Vertical sharing: union/state/local levels","Federalism: constitutionally organised multi-level authority","Accountability: ability to explain decisions and face review/consequences"],
    [
      {title:"Evaluate a power-sharing arrangement",steps:["Name the type of power sharing shown.","Identify which actors/institutions receive authority.","Explain how the arrangement prevents concentration or accommodates diversity.","State one strength and, if asked, one limitation."]},
      {title:"Analyse a democratic reform",steps:["Identify the problem the reform is meant to address.","Describe the legal/process change.","Explain how behaviour or incentives may change.","Mention one implementation condition or possible unintended effect."]}
    ],
    ["Calling any administrative decentralisation a fully federal arrangement.","Listing the functions of parties without evaluating their importance or limitations.","Claiming elections alone guarantee all democratic outcomes.","Using an example without connecting it to the political concept."],
    ["Use the prescribed case studies and constitutional vocabulary. Answer 'why' through institutional effects and 'how' through process; make a reasoned judgement for 'evaluate'."],
    ["How does horizontal power sharing differ from vertical sharing?","Why are elections necessary but insufficient for democratic quality?","What conditions make local decentralisation meaningful?"],
    ["Federalism: constitutionally allocated authority across levels.","Decentralisation: transfer/devolution of decision-making closer to local units.","Accountability: mechanisms requiring officials/institutions to explain and justify actions."]);

  const g10Economics=guide("Class 10","Social Science","CBSE Class 10 Economics — Development, Sectors, Money, Credit and Globalisation",
    "A concept guide linking income and non-income well-being, employment structure, financial systems, trade and economic interdependence.",
    [
      {heading:"Development and indicators",body:"Development goals differ across people because individuals value income, security, dignity, freedom, equality, health, education and environmental quality differently. Per-capita income is an average and can hide distribution. Comparisons of development should use suitable indicators and explain their limitations. Public services matter because private purchasing power alone does not guarantee equal access to schooling, healthcare, sanitation or clean water."},
      {heading:"Sectors of the economy and employment",body:"Primary activities use natural resources, secondary activities process materials, and tertiary activities provide services; in practice many jobs connect all three. Employment can be classified by ownership, formal/informal conditions and stability. Underemployment occurs when people work fewer hours or at lower productivity than possible, including situations where extra workers add little output. Policies to improve employment need demand, skills, infrastructure and access to markets, not merely moving workers between sector labels."},
      {heading:"Money and formal/informal credit",body:"Money solves the double-coincidence problem of barter and functions as a medium of exchange, unit of account, store of value and means of payment. Banks accept deposits and lend, subject to liquidity and prudential rules. Credit can support productive activity when returns exceed costs, but can create a debt trap when repayment is impossible or terms are unfair. Compare loan sources by interest, collateral, documentation, reliability, access and consequences of default."},
      {heading:"Globalisation and production networks",body:"Globalisation links economies through trade, investment, technology, information and supply chains. Multinational firms may spread production across countries based on labour, infrastructure, market access, policy and cost. Effects are uneven: some workers/producers gain markets and jobs while others face competition, insecure work or unequal bargaining power. Trade liberalisation changes conditions, but infrastructure, worker skills, regulation and fair competition shape who benefits."},
      {heading:"Case answers and data interpretation",body:"Use a clear economic concept rather than a moral judgement. For a loan case, compare repayment capacity and conditions. For development, distinguish averages from distribution and non-income measures. For sector employment, identify productivity and worker conditions. A data response should state the observed pattern, compare groups and suggest a supported explanation; do not infer causation solely from two numbers changing together."}
    ],
    ["Per-capita income = national income / population","Loan cost includes interest, fees and other stated repayment obligations","Formal credit: regulated/documented lender; informal credit: less formally regulated source"],
    [
      {title:"Compare development indicators",steps:["State what the indicator measures.","Explain one strength, such as comparability or simplicity.","Explain one limitation, such as inequality hidden by an average.","Use an additional health/education/environment indicator if relevant."]},
      {title:"Decide whether credit is productive",steps:["Identify the purpose and expected cash/income benefit.","Calculate or compare repayment obligation with realistic income.","Examine interest, collateral, schedule and risk.","Conclude conditionally: credit helps when benefits and repayment capacity match the terms."]}
    ],
    ["Treating income as the only development measure.","Assuming all credit is beneficial or all debt is harmful.","Equating service-sector growth with secure employment for everyone.","Claiming globalisation affects all regions and workers identically."],
    ["Use examples from the prescribed chapter, but explain the economic mechanism. Separate average income, distribution and public provision."],
    ["Why can per-capita income hide inequality?","How can credit create either opportunity or a debt trap?","Why are globalisation's gains uneven?"],
    ["Per-capita income: average income per person.","Underemployment: labour used below its productive potential or desired level.","Collateral: asset pledged to secure a loan."]);

  const g10English=guide("Class 10","English","CBSE Class 10 English — Reading, Writing and Literature Answer Guide",
    "A detailed skill sheet for comprehension, formal writing, analytical paragraphs, poetry/prose interpretation and grammar checking.",
    [
      {heading:"Reading comprehension",body:"Read the questions first only to identify the type of evidence needed, then read the passage for main idea, structure and tone. For inference questions, separate what the passage states explicitly from what the evidence supports. Match the answer's scope to the question: a one-detail question does not need a paragraph, while an evaluation question needs reasoning. Avoid copying long sections; express the idea accurately in your own words and keep the original meaning."},
      {heading:"Formal letters, articles and analytical paragraphs",body:"Follow the prescribed format for the task and session: sender/recipient/date/subject where required, salutation, clear opening, organised points and an appropriate closing. An article uses a title/headline and a clear audience-focused voice. An analytical paragraph should describe the key trend, compare categories, cite important values and finish with an evidence-based overall observation; do not invent data not present in a chart. Format errors are avoidable if you memorise a short checklist."},
      {heading:"Literature: theme, character and evidence",body:"A strong literature response makes a claim about theme/character, supports it with an accurate incident, image, choice or line detail, and explains how the evidence proves the claim. Do not retell the whole plot when the prompt asks about one decision or theme. For poetry, comment on the image, tone, sound/device or contrast and its effect; identifying a device without explaining its effect usually remains incomplete."},
      {heading:"Grammar and editing",body:"Grammar questions test context, not only isolated rules. Check subject–verb agreement, tense consistency, pronoun reference, articles, prepositions, reported speech and sentence structure according to the syllabus. When editing, read the entire sentence to see what meaning and time relationship are required. Avoid replacing words mechanically if it changes tense, register or sense."},
      {heading:"Planning under time pressure",body:"Allocate time according to marks and complexity. Underline command words such as analyse, infer, compare, justify and evaluate. Sketch a 3-point plan before a longer response. Reserve a final proofread for format, word limit, tense, names and whether each paragraph answers the exact prompt. Clear, direct sentences are more reliable than memorised, unrelated quotations or ornamental phrases."}
    ],
    ["Claim → evidence → explanation is a reliable literature-response structure","Analytical paragraph: overall pattern → comparisons → evidence/data → inference","Formal writing: purpose → audience → required format → organised content → closing"],
    [
      {title:"Build a literature answer",steps:["State the interpretation in one direct sentence.","Select a specific incident, image or character choice from the text.","Explain the link between that evidence and the interpretation.","End by connecting back to the question's theme/character/decision."]},
      {title:"Describe a chart",steps:["Identify the main trend or category with the largest/smallest value.","Compare at least two relevant categories using the given values.","State a supported implication, avoiding invented causes.","Check the paragraph stays within the word limit and doesn't simply list every number."]}
    ],
    ["Retelling the plot instead of answering the prompt.","Naming a poetic device without explaining its effect.","Adding made-up chart statistics or unsupported causes.","Ignoring the prescribed writing format and word limit."],
    ["Use the current CBSE sample paper and marking scheme for exact formats. The guide gives method, not a substitute for studying prescribed texts or practising writing."],
    ["What is the difference between explicit detail and inference?","What makes a literature point evidence-based?","What should an analytical paragraph say beyond listing values?"],
    ["Inference: conclusion supported by evidence but not stated verbatim.","Tone: speaker/author's attitude conveyed by language.","Analytical paragraph: evidence-led description and interpretation of data."]);

  const g10Hindi=guide("Class 10","Hindi","CBSE Class 10 Hindi — Reading, Writing, Grammar and Literature Guide",
    "A flexible Hindi revision guide for पाठ-बोध, व्याकरण, रचनात्मक लेखन and साहित्यिक उत्तर construction; verify Course A/B and exact पाठ list.",
    [
      {heading:"अपठित गद्यांश/पद्यांश",body:"प्रश्नों को पढ़कर यह पहचानें कि उत्तर प्रत्यक्ष जानकारी, मुख्य विचार, शब्दार्थ या निष्कर्ष पर आधारित है। गद्यांश/पद्यांश में उपलब्ध प्रमाण के आधार पर उत्तर दें। अपने शब्दों में लिखते समय मूल अर्थ न बदलें और अनावश्यक विस्तार न करें। 'क्यों', 'कैसे' और 'क्या संदेश है' जैसे प्रश्न अलग प्रकार के उत्तर माँगते हैं: कारण, प्रक्रिया और व्याख्या।"},
      {heading:"व्याकरण की तैयारी",body:"व्याकरण प्रश्नों में केवल परिभाषा याद करना पर्याप्त नहीं; वाक्य में नियम लागू करना आवश्यक है। पद-परिचय, वाक्य-रचना, समास/संधि या अन्य पाठ्य-विषयों के लिए अपनी निर्धारित पाठ्य-पुस्तक और पाठ्यक्रम की सूची के अनुसार अभ्यास करें। शब्द का रूप, लिंग, वचन, कारक, काल और वाक्य में उसका कार्य जाँचें। नियम में अपवाद हो तो उसे उदाहरण के साथ अलग नोट करें।"},
      {heading:"अनुच्छेद, पत्र और सूचना जैसे लेखन कार्य",body:"लेखन से पहले उद्देश्य और पाठक तय करें। अनुच्छेद में विषय-वाक्य, क्रमबद्ध विचार, उदाहरण/तर्क और निष्कर्ष रखें। औपचारिक पत्र या सूचना में निर्धारित प्रारूप, विषय, स्पष्ट भाषा और शब्द-सीमा का पालन करें। सजावटी लेकिन अप्रासंगिक वाक्यों के बजाय सही जानकारी और सुसंगत क्रम अधिक उपयोगी हैं। प्रश्न में माँगे गए सभी बिंदुओं को पूरा करें।"},
      {heading:"साहित्यिक उत्तर",body:"कविता/गद्य का उत्तर देते समय प्रसंग, पात्र/वक्ता, प्रमुख विचार और पाठ से प्रमाण का उपयोग करें। कथानक को पूरा दोहराने के बजाय प्रश्न में पूछे गए गुण, निर्णय, भावना या संदेश पर केन्द्रित रहें। काव्य-भाषा के बिम्ब, प्रतीक या अलंकार की पहचान के साथ उसका प्रभाव भी बताएँ। पाठ्यक्रम में निर्धारित पाठ और पात्रों के नाम सही लिखें।"},
      {heading:"उत्तर जाँचने की रणनीति",body:"अंत में मात्रा, वर्तनी, विराम-चिह्न, वाक्य-सम्बन्ध और शब्द-सीमा जाँचें। यदि प्रश्न में 'दो कारण' माँगे गए हों तो दो अलग कारण दें, एक ही बात को दो रूपों में न लिखें। साहित्यिक उत्तर में पाठ से जुड़ी घटना/वाक्य का उल्लेख करें, लेकिन गलत उद्धरण या अप्रमाणित पृष्ठ-संख्या न बनाएँ।"}
    ],
    ["उत्तर संरचना: मुख्य विचार → प्रमाण/उदाहरण → व्याख्या → निष्कर्ष","लेखन जाँच: प्रारूप + उद्देश्य + सभी माँगे गए बिंदु + शब्द-सीमा + भाषा"],
    [
      {title:"साहित्यिक उत्तर की रूपरेखा",steps:["प्रश्न के मुख्य शब्द को पहचानें: पात्र, संदेश, भाव, निर्णय या भाषा।","पहले वाक्य में सीधा उत्तर दें।","पाठ की सटीक घटना/उदाहरण दें।","बताएँ कि उदाहरण प्रश्न के उत्तर को कैसे सिद्ध करता है।"]},
      {title:"अपठित गद्यांश",steps:["मुख्य विचार और आवश्यक तथ्य चिन्हित करें।","प्रत्येक उपप्रश्न का अलग उत्तर दें।","निष्कर्ष प्रश्न के प्रमाण से निकालें, बाहरी अनुमान न जोड़ें।","अंत में जाँचें कि उत्तर सीधे प्रश्न को संबोधित करता है।"]}
    ],
    ["कथानक का अनावश्यक सार लिखना.","पाठ्यक्रम/कोर्स A या B की निर्धारित सामग्री की जगह गलत पाठ याद करना.","लेखन के प्रारूप और शब्द-सीमा को अनदेखा करना.","व्याकरण में वाक्य का संदर्भ देखे बिना नियम लगाना."],
    ["अपने विद्यालय के वर्तमान CBSE Course A/B पाठ्यक्रम से पाठ-सूची सत्यापित करें। यह मार्गदर्शिका उत्तर-लेखन की विधि देती है, किसी विशिष्ट पाठ का पूर्ण सारांश नहीं."],
    ["किसी साहित्यिक उत्तर को प्रमाण-आधारित कैसे बनाते हैं?","अपठित गद्यांश में निष्कर्ष कैसे निकाला जाता है?","लेखन कार्य में प्रारूप और शब्द-सीमा क्यों ज़रूरी हैं?"],
    ["प्रसंग: पाठ/वाक्य की स्थिति और संदर्भ.","बिम्ब: भाषा से बनने वाला दृश्य/अनुभूति-चित्र.","निष्कर्ष: उपलब्ध प्रमाण और तर्क से निकला अंतिम विचार."]);

  const g11Accountancy=guide("Class 11","Accountancy","CBSE Class 11 Accountancy — Accounting Equation, Journal, Ledger and Trial Balance",
    "Understand the accounting cycle and double-entry logic, then practise journal-to-ledger-to-trial-balance steps.",
    [
      {heading:"Accounting equation and transaction analysis",body:"The basic accounting equation is Assets=Liabilities+Capital/Equity. Every transaction changes at least two accounting elements while preserving the equation. Owner investment increases assets and capital; a cash purchase of equipment exchanges one asset for another; a credit purchase of goods increases inventory/purchases and a payable under the applicable recording system. Analyse the transaction before selecting debit/credit accounts; do not treat debit as automatically 'increase' in every account type."},
      {heading:"Debit-credit rules and journal entries",body:"Double entry records equal total debits and credits for each transaction. Under the traditional rules, personal, real and nominal accounts are handled with taught debit/credit rules; modern classification by assets, liabilities, equity, revenue and expenses is a helpful cross-check. A journal entry includes date, accounts, amounts and a narration explaining the event. Choose the accounts from economic substance, not simply the words 'paid' or 'received'."},
      {heading:"Ledger posting and balancing",body:"A ledger groups transactions by account so that the account's running effect can be reviewed. Journal debits are posted to the debit side of the corresponding ledger and credits to the credit side. Balance each account by comparing totals, carrying the difference to the smaller side and bringing it down as required. Keep dates, particulars and references consistent. Posting errors can survive if both debit and credit are misposted in matching ways."},
      {heading:"Trial balance and error limits",body:"A trial balance lists ledger balances to check whether total debits equal total credits. It helps detect certain arithmetic/posting errors but does not prove that every transaction is correct. A complete omission, error of principle, compensating error or entry in the wrong account on the correct side may leave totals equal. When totals differ, check arithmetic, ledger balance and posting direction systematically rather than changing numbers to force agreement."},
      {heading:"Accounting as information",body:"Financial accounting summarises past transactions for decision-makers; concepts such as consistency, prudence, accrual and going concern guide how events are recognised/reported in the prescribed framework. Cash received is not always revenue for the period, and cash paid is not always expense. Match the recognition rule to the question. Always follow the prescribed current CBSE syllabus and account format."}
    ],
    ["Assets = Liabilities + Capital/Equity","Total debits = total credits for each journal entry","Trial balance: sum of debit balances should equal sum of credit balances"],
    [
      {title:"Record a cash purchase of equipment",steps:["Identify equipment as an asset increasing and cash as an asset decreasing.","Debit Equipment/Equipment Account and credit Cash/Bank under the prescribed journal convention.","Enter equal amounts on both sides and write a concise narration.","The accounting equation remains balanced because one asset rises while another falls."]},
      {title:"Trace a journal to a trial balance",steps:["Record each transaction in the journal with equal debit/credit totals.","Post each line to the relevant ledger account on the same side.","Balance ledger accounts and determine debit/credit closing balances.","List balances in the trial balance and compare column totals; investigate differences rather than assuming equality proves completeness."]}
    ],
    ["Treating debit as always an increase and credit as always a decrease.","Confusing cash flow with revenue/expense recognition.","Assuming a balanced trial balance proves all entries correct.","Skipping narration or ledger references in a required format."],
    ["Show transaction analysis, journal entry, postings and balances stepwise. Keep working neat so arithmetic and account selection can be checked independently."],
    ["Why can a trial balance agree despite a mistake?","What does the accounting equation represent?","Why is cash receipt not always revenue?"],
    ["Ledger: account-wise record of transactions.","Trial balance: list of ledger balances to check debit-credit equality.","Accrual: recognition based on earning/incurring rather than only cash movement."]);

  const g11Economics=guide("Class 11","Economics","CBSE Class 11 Economics — Statistics, Data Presentation and Introductory Microeconomics",
    "A structured guide to data collection, central tendency, dispersion, correlation, demand/supply and market equilibrium.",
    [
      {heading:"Data collection and presentation",body:"Define the objective, population and variables before collecting data. Primary data are collected first-hand for the purpose; secondary data already exist and must be checked for reliability, date, coverage and definitions. Tables should have clear titles, units and totals; graphs must use suitable scales and labels. A graph can mislead if axes are truncated, categories differ in size or percentages are compared without a common base."},
      {heading:"Mean, median, mode and dispersion",body:"The mean uses every observation but is affected by extreme values. The median locates the middle after ordering; mode is the most frequent value/class. For grouped data use frequencies and class marks where the method requires them. Range, quartile deviation, mean deviation and standard deviation describe spread in different ways. A measure should be interpreted alongside units and the shape of the distribution rather than treated as a stand-alone verdict."},
      {heading:"Correlation and index numbers",body:"Correlation describes the direction/strength of association, not proof that one variable causes the other. A third factor or selection process may influence both. Index numbers compare a variable or group of variables relative to a base period; their meaning depends on base-year choice, item selection, weighting and data quality. State what the index compares and avoid saying that an index is an absolute amount."},
      {heading:"Demand, supply and equilibrium",body:"Demand describes the quantities buyers are willing and able to purchase at different prices, holding other factors constant. A change in the good's own price produces movement along a demand curve; income, preferences, related-good prices and expectations can shift the curve. Supply similarly depends on cost, technology, taxes and expectations. Market equilibrium occurs where quantity demanded equals quantity supplied; a shortage or surplus creates pressure for price to adjust under the basic competitive model."},
      {heading:"Elasticity and economic interpretation",body:"Price elasticity of demand measures percentage change in quantity demanded relative to percentage change in price. Elasticity is not the same as slope because slope uses absolute changes and depends on units. Interpretation depends on substitutes, necessity, time and budget share. When answering a case, identify which variable changes and whether it causes movement along a curve or a shift of the whole curve."}
    ],
    ["Arithmetic mean=Σx/n; frequency mean=Σfx/Σf","Range=max−min","Price elasticity of demand=percentage change in quantity demanded / percentage change in price","Market equilibrium: Q_d=Q_s"],
    [
      {title:"Compare mean and median",steps:["Order the observations to find the median.","Calculate the arithmetic mean using every value.","Inspect whether an extreme value changes the mean more than the median.","Choose the measure that answers the question and explain the distribution's context."]},
      {title:"Demand shift versus movement",steps:["Ask whether the good's own price changed or another determinant changed.","Own-price change leads to movement along an unchanged curve.","Income, preferences, expectations or prices of related goods can shift demand.","Explain equilibrium impact using both demand and supply rather than assuming price always changes in the same direction."]}
    ],
    ["Calling correlation proof of causation.","Using mean when the question asks for median or mode.","Confusing a demand shift with movement along demand.","Interpreting a slope as elasticity without percentage changes."],
    ["Write formula, substitute data and explain the meaning in words. In microeconomics diagrams label axes, curves, equilibrium and the direction of shift."],
    ["Why can median be more robust to outliers?","What is the difference between demand shift and movement along demand?","Why does correlation not establish causation?"],
    ["Secondary data: data collected earlier for another or broader purpose.","Dispersion: measure of spread among observations.","Elasticity: responsiveness measured through percentage changes."]);

  const g11CS=guide("Class 11","Computer Science","CBSE Class 11 Computer Science — Python, Algorithms, Data Types and Data Handling",
    "Detailed programming notes for algorithms, data types, expressions, selection/loops, functions, collections and reliable debugging.",
    [
      {heading:"Problem-solving and algorithms",body:"Before coding, write the input, expected output, assumptions and edge cases. An algorithm is a finite, unambiguous sequence of steps; pseudocode and flowcharts help reveal missing branches. Test normal input, boundary values, empty input where permitted and invalid types. Correctness is about whether the result matches the specification, not merely whether the program runs without crashing."},
      {heading:"Variables, data types and expressions",body:"Python variables refer to objects; assignment binds a name to a value. Types affect permitted operations and results. Integer division and ordinary division differ; operator precedence can change an expression, so use parentheses for clarity. A string is a sequence of characters; indexes start at zero and slicing has a stop index that is excluded. Mutable collections can change in place, while immutable objects do not change their contents in place."},
      {heading:"Selection, loops and tracing",body:"If/elif/else branches are evaluated in order; conditions should be mutually clear to avoid an earlier branch capturing a case intended for a later branch. A for loop iterates over an iterable; a while loop repeats while a condition remains true. For loops that never update a condition may run forever. Trace tables listing variable values at each iteration are useful for nested loops and accumulators."},
      {heading:"Functions and decomposition",body:"A function gives a reusable name to a unit of work. Parameters receive input; return sends a result back to the caller, while print displays output and does not substitute for return. Local variables normally exist within the function's scope. Break a large task into functions with clear responsibilities and use meaningful names. Test each function on its own before integrating it."},
      {heading:"Lists, tuples, dictionaries and data quality",body:"Lists are ordered and mutable, tuples are ordered and immutable in their structure, and dictionaries map unique keys to values. Choose a structure based on how data are accessed, updated and represented. Validate input at boundaries, avoid assuming every field exists and distinguish a missing value from a valid zero/empty string. Use examples that cover duplicates, empty collections and out-of-range indexes."}
    ],
    ["Sequence index starts at 0; a slice stop index is excluded","for loop: iterate through an iterable; while loop: repeat while a condition is true","return sends a value to caller; print displays output","List: ordered/mutable; tuple: ordered/immutable; dict: key-value mapping"],
    [
      {title:"Trace a loop",steps:["Write the initial variable values.","For each iteration, record condition, body operations and updated values.","Check the termination condition after the update.","Compare the final variable state with the expected output."]},
      {title:"Design a function",steps:["Name the task in one sentence.","Identify input parameters and validation needed.","Decide whether the result should be returned, displayed or both.","Test typical and boundary inputs before calling it from a larger program."]}
    ],
    ["Using print where a caller needs a returned value.","Off-by-one errors in range/slices.","Changing a loop variable or condition incorrectly.","Assuming user input is automatically converted to a number."],
    ["For programming answers include code indentation, sample input/output and a short trace for tricky loops. Explain why a data structure suits the task."],
    ["Why is return different from print?","How do list and tuple mutability differ?","What produces an off-by-one error in slicing?"],
    ["Algorithm: finite, ordered problem-solving steps.","Mutable object: object whose contents can change.","Scope: region where a variable name is accessible."]);

  const g12Accountancy=guide("Class 12","Accountancy","CBSE Class 12 Accountancy — Partnership, Company Accounts and Cash Flow",
    "A workflow for partnership adjustments, reconstitution, company share transactions and cash-flow classification.",
    [
      {heading:"Partnership fundamentals and adjustments",body:"A partnership distributes profit according to the agreement. Interest on capital, salary/commission to a partner, interest on drawings and guarantee adjustments depend on the terms stated. Read whether an item is an appropriation of profit or a charge against profit under the prescribed approach. When a partner joins/leaves or the ratio changes, compare old and new profit-sharing ratios to determine gaining/sacrificing shares; revaluation and goodwill adjustments must follow the specific event."},
      {heading:"Revaluation, goodwill and capital accounts",body:"Revaluation updates assets/liabilities to agreed values and records unrecorded items; the gain/loss is allocated to partners in the appropriate old ratio for common reconstitution cases. Goodwill compensates for future earning capacity and is adjusted based on the gaining/sacrificing relationship. Fixed and fluctuating capital methods use different account layouts: under fixed capital, routine items may flow through current accounts; do not post a drawing or salary into the wrong account."},
      {heading:"Company share transactions",body:"Share capital can involve application, allotment and calls. Oversubscription may require proportionate allotment or refund, depending on the stated facts. Calls in arrears are amounts due but unpaid; calls in advance are received before they become due and are treated according to the prescribed rules. Forfeiture and reissue require tracking the amount received, amount due and capital/reserve treatment under the stated method."},
      {heading:"Cash-flow statement",body:"Operating activities relate to principal revenue-producing activity; investing activities concern acquisition/disposal of long-term assets and investments; financing activities change equity and borrowing. Under the indirect method, start from the specified profit figure, adjust non-cash/non-operating items and changes in working capital, then treat interest/dividends/tax according to the applicable syllabus convention and data. A purchase of equipment is not an operating cash flow merely because the company uses it daily."},
      {heading:"Presentation and reconciliation",body:"Accountancy marks depend on method and layout as well as arithmetic. Show the ratio calculation, adjustment entry, ledger/account and balance effect in an understandable order. Where information is missing, state the prescribed assumption only if the question permits it. Reconcile totals and verify that the final balance sheet equation/cash balance or share-capital figure follows from the entries."}
    ],
    ["Sacrificing ratio = old share − new share for a sacrificing partner","Gaining ratio = new share − old share for a gaining partner","Cash flow categories: operating / investing / financing"],
    [
      {title:"Compute a ratio change",steps:["Write each partner's old profit share and new profit share as fractions.","Sacrifice = old − new; gain = new − old.","Use the resulting ratios to allocate goodwill/revaluation according to the event and syllabus rule.","Check that the total gain equals total sacrifice in a simple reconstitution."]},
      {title:"Classify cash flows",steps:["Identify the transaction's nature, not merely its account name.","Daily revenue-producing operations normally fall under operating activity.","Buying/selling long-term assets and investments normally fall under investing activity.","Changes in share capital and borrowings normally fall under financing activity; apply the stated exam convention to interest, dividend and tax."]}
    ],
    ["Using gaining ratio where sacrificing ratio is requested.","Treating every cash payment as operating cash flow.","Mixing fixed and fluctuating capital-account methods.","Skipping working notes for interest or proportionate allotment calculations."],
    ["In long numerical questions show working notes for ratios, valuation adjustments, goodwill and working capital. Use prescribed CBSE formats and current accounting conventions."],
    ["What is the difference between gaining and sacrificing ratio?","How are investing and financing cash flows distinguished?","Why does the question's capital method matter?"],
    ["Revaluation: adjustment of asset/liability values on reconstitution.","Calls in arrears: amounts called but not paid by shareholders.","Working capital: current assets minus current liabilities."]);

  const g12Economics=guide("Class 12","Economics","CBSE Class 12 Economics — National Income, Money, Budget and Balance of Payments",
    "Explain macroeconomic aggregates, circular flow, banking, fiscal policy, aggregate demand and external-sector accounts.",
    [
      {heading:"National income accounting",body:"GDP measures value of final goods/services produced within domestic territory during a period. Gross/net distinguishes depreciation; domestic/national distinguishes factor income by territory versus resident ownership under the prescribed definition. Market prices and factor cost differ by indirect taxes/subsidies in traditional textbook approaches; follow the current syllabus terminology. Avoid double counting intermediate goods, and include only the output boundary specified by the question."},
      {heading:"Circular flow and aggregate demand",body:"Households provide factors and receive incomes; firms pay factor incomes and sell output. Savings, taxes and imports can act as leakages from a simple expenditure flow, while investment, government spending and exports are injections. Aggregate demand components depend on the exact model and syllabus. In a simple income-expenditure model, equilibrium occurs where planned aggregate expenditure equals output/income, but the model makes simplifying assumptions about prices and capacity."},
      {heading:"Money and banking",body:"Money serves exchange, account and value functions. Commercial banks accept deposits, hold reserves and extend credit. Central-bank tools can influence liquidity, interest conditions and credit creation. In a simplified deposit-multiplier model, reserve requirements limit repeated lending; real banks face capital, liquidity, credit risk and demand constraints, so the textbook ratio should not be treated as an exact universal predictor."},
      {heading:"Government budget and fiscal policy",body:"A government budget lists receipts and expenditure. Revenue receipts do not create a liability or reduce assets in the same way as capital receipts; revenue expenditure generally does not create an asset, while capital expenditure may create assets or reduce liabilities under the prescribed classification. Deficits measure different gaps: fiscal deficit is total expenditure minus total receipts excluding borrowings in the standard school definition; revenue deficit compares revenue expenditure and revenue receipts. Fiscal policy can support activity but affects debt and resource allocation."},
      {heading:"Balance of payments and exchange rate",body:"The current account records trade in goods/services, primary income and current transfers; the capital/financial-side classification follows the course's convention for asset/liability transactions. A balance-of-payments identity balances accounting entries, even when a current-account deficit creates a financing need. Exchange-rate changes influence import prices, export competitiveness, foreign-currency liabilities and inflation with lags and other factors. Do not assume depreciation always improves the trade balance immediately."}
    ],
    ["GDP = value of final domestic production over the period","Fiscal deficit = total expenditure − receipts excluding borrowings in the standard school definition","Revenue deficit = revenue expenditure − revenue receipts","Simple money/deposit multiplier relation is model-specific; use the exact textbook definition given"],
    [
      {title:"Avoid double counting",steps:["Classify each good as intermediate or final relative to the stated production chain.","Use value added at each production stage or count only final goods/services.","Exclude second-hand goods themselves while accounting for current services associated with resale if specified.","State territory/time period and whether GDP/GNP/net/gross is requested."]},
      {title:"Classify a budget item",steps:["Ask whether the receipt creates a liability or reduces an asset.","Ask whether expenditure creates an asset or reduces a liability.","Classify the item as revenue or capital under the prescribed definitions.","Use the stated entries to compute deficit measures, preserving the correct numerator and denominator."]}
    ],
    ["Counting an intermediate good and the final good's full value twice.","Confusing current account with all capital/financial transactions.","Calling all public expenditure revenue expenditure.","Assuming a deposit multiplier is an exact real-world forecast."],
    ["Define the aggregate, show the identity/formula and explain each component. Macro answers should distinguish measurement identity from causal theory."],
    ["What is double counting?","How are revenue and capital receipts different?","Why does a balance-of-payments statement balance by accounting identity?"],
    ["GDP: final domestic production value over a period.","Fiscal deficit: financing gap as defined in the budget framework.","Current account: goods/services plus specified income and transfer flows."]);

  const g12Business=guide("Class 12","Business Studies","CBSE Class 12 Business Studies — Management, Finance, Marketing and Consumer Protection",
    "Organise case-study answers around the management function, principle, financial decision, marketing mix or consumer right actually illustrated.",
    [
      {heading:"Nature and functions of management",body:"Management coordinates people and resources to achieve organisational objectives efficiently and effectively. Planning sets objectives and paths; organising structures roles/resources; staffing fills positions and develops people; directing guides and motivates work; controlling compares performance with standards and corrects deviations. The functions form a cycle: control feedback can change the next plan. Case answers should name the function and point to a specific clue rather than listing every function."},
      {heading:"Principles and business environment",body:"Management principles are general guidelines that require judgement in context, not mechanical laws. A business environment includes economic, social, technological, political/legal and competitive forces. A change in technology, consumer preferences or regulation can create both opportunity and threat. In a case, quote the change given, classify it and explain the decision it may require; do not infer a detailed policy change from an unspecified trend."},
      {heading:"Organisation, staffing and leadership",body:"Organisational structure allocates authority, responsibility and reporting relationships. Delegation transfers authority for assigned work while ultimate accountability remains with the delegator in the standard management distinction; decentralisation spreads decision authority more broadly. Staffing covers recruitment, selection, placement, training and development. Direction involves supervision, motivation, leadership and communication, whose effects depend on task, people and organisational context."},
      {heading:"Financial management and planning",body:"Financial management includes investment, financing and dividend decisions. Working capital deals with short-term operational needs; fixed capital supports long-term assets. The financing mix balances cost, risk, control and flexibility. Financial planning estimates funds needed and prevents both shortages and idle excess. In a case, distinguish a long-term asset decision from inventory/receivables/payables, and identify what the data say about risk/return rather than guessing a 'best' choice."},
      {heading:"Marketing and consumer protection",body:"Marketing is broader than selling and includes understanding needs, product planning, price, place/distribution, promotion and customer relationships. The four Ps are interconnected; price decisions depend on cost, competition, customer value and objectives. Consumer protection includes accurate information, safety, choice, redress and responsibilities under applicable law. Use the current prescribed legal/consumer framework, and distinguish an ethical concern from a specific enforceable right."}
    ],
    ["Management cycle: planning → organising → staffing → directing → controlling → feedback","Marketing mix: product, price, place, promotion","Financial decisions: investment, financing and dividend"],
    [
      {title:"Solve a management case",steps:["Underline the action/clue described in the case.","Match it to the most specific management function/principle.","Quote the clue in brief and explain the connection.","Avoid listing unrelated features of the entire chapter."]},
      {title:"Analyse a marketing decision",steps:["Identify target customer need and product value.","Analyse the relevant P (product, price, place or promotion) and its trade-off.","Connect it to cost, competition or distribution facts in the case.","State the likely outcome without assuming unsupported market data."]}
    ],
    ["Naming a function without evidence from the case.","Confusing delegation with decentralisation.","Equating marketing with advertising alone.","Using an outdated legal description without checking the prescribed session."],
    ["Case-study answers should use textbook terminology, identify a cue and then explain it. For evaluate questions, mention both advantage and limitation in context."],
    ["How is delegation different from decentralisation?","Why does controlling feed into planning?","What are the four elements of the marketing mix?"],
    ["Delegation: assignment of authority/responsibility for a task to a subordinate.","Working capital: resources needed for day-to-day operations.","Marketing mix: coordinated product, price, place and promotion decisions."]);

  const g12CS=guide("Class 12","Computer Science","CBSE Class 12 Computer Science — Python Functions, Files, SQL and Networks",
    "A practical guide to algorithm tracing, functions, data structures, file handling, relational databases and basic networking.",
    [
      {heading:"Functions and parameter passing",body:"Functions break a program into reusable units with documented inputs and outputs. Local variables normally exist within function scope; a returned value becomes available to the caller, while print only produces display output. Default arguments and mutable objects require care: a mutable default can persist across calls if changed. For recursive functions, identify the base case and ensure each recursive call moves toward it."},
      {heading:"Stacks, queues and complexity",body:"A stack is LIFO: the most recently inserted item is removed first. A queue is FIFO: the earliest inserted item is removed first. Trace push/pop or enqueue/dequeue operations in order and track underflow/overflow conditions where the model specifies capacity. Complexity describes how work or storage grows with input size; Big-O is an asymptotic upper-bound notation, not an exact time in seconds."},
      {heading:"Text/binary file handling",body:"Opening a file establishes a mode and resource; reading/writing methods operate according to text or binary representation. Use with/open patterns where taught so the file closes reliably. File pointers and read positions matter: a read can consume the remaining content and a subsequent read may return empty until the pointer is repositioned. Validate whether a task asks for read, readline, readlines, write or append mode."},
      {heading:"SQL and relational databases",body:"A relational table represents rows/records and columns/attributes. A primary key uniquely identifies a row and cannot be null under the standard relational notion; a foreign key references a key in another table and can support referential integrity. SELECT chooses columns, WHERE filters rows, GROUP BY forms groups for aggregate calculations, HAVING filters groups and ORDER BY sorts results. SQL logical processing order differs from the written order; aliases and aggregate conditions must be used correctly."},
      {heading:"Networks and cyber safety",body:"A network connects devices to share data/resources. LAN, MAN and WAN differ by geographic scope; topology describes connection layout. Protocols define communication rules. IP addresses identify network interfaces at the network layer, while domain names are resolved through DNS. HTTPS uses TLS to protect transport between client and server, but it does not guarantee that a website's claims are true or that a user will avoid phishing. Security also requires authentication, updates, least privilege and careful handling of personal data."}
    ],
    ["Stack: LIFO; queue: FIFO","Primary key: unique row identifier; foreign key: reference to a key in another table","SQL: SELECT columns FROM table WHERE row_condition GROUP BY columns HAVING group_condition ORDER BY sort_key","Use with/open for reliable file closure"],
    [
      {title:"Trace stack operations",steps:["Start with an empty stack.","Apply each push in order and record the top item.","On pop, remove only the current top item.","Check empty-stack/overflow conditions against the problem's assumptions."]},
      {title:"Write a grouped SQL query",steps:["Identify output columns and required aggregate.","Filter individual rows with WHERE before grouping.","Group by each non-aggregated output column.","Use HAVING for conditions on group aggregates and ORDER BY for final presentation."]},
      {title:"File-reading logic",steps:["Open the file with the required mode/encoding.","Read according to the specified method and pointer state.","Process each line/record without assuming extra whitespace or valid fields.","Close the file using a context manager or the taught close pattern."]}
    ],
    ["Using print instead of return in a function used by another function.","Mixing LIFO and FIFO behaviour.","Using HAVING where a row-level WHERE filter is required.","Assuming HTTPS proves a website is trustworthy."],
    ["For code, include indentation and sample output. For SQL, show exact table/column names from the prompt and distinguish row filtering from aggregate filtering. For networks, state layer/scope."],
    ["How does pop differ from dequeue?","What is the difference between WHERE and HAVING?","Why does HTTPS not eliminate phishing risk?"],
    ["Primary key: unique key used to identify a row.","DNS: system mapping domain names to network addresses.","LIFO/FIFO: last-in-first-out / first-in-first-out ordering."]);

  const g12Humanities=guide("Class 12","Humanities","CBSE Class 11–12 Humanities — Source Analysis, Concepts and Long-Answer Method",
    "A cross-subject method for History, Political Science, Geography, Psychology and Sociology: define, contextualise, support and evaluate.",
    [
      {heading:"Conceptual definitions",body:"Start with the definition used by the prescribed subject text, then explain the concept in simpler words and distinguish it from nearby terms. In social sciences, concepts such as power, identity, development, culture, institution and socialisation have specific disciplinary meanings. Use an example only after you state the concept. Do not treat a common everyday use as automatically identical to the academic definition."},
      {heading:"Evidence, cases and comparison",body:"For a source or case, identify the setting, actors, evidence, point of view and question being asked. Compare cases using the same dimensions; otherwise, a comparison becomes a list of unrelated facts. In geography, use spatial pattern and scale. In history, use chronology and causation. In political science, identify institutions and authority. In psychology/sociology, distinguish observed behaviour from interpretation and recognise limitations of a sample or method."},
      {heading:"Cause, process and consequence",body:"A strong long answer links conditions to mechanisms and outcomes. One structure is: define the issue; explain background/causes; describe the process or institution; assess impacts on different groups; provide a balanced conclusion. Use topic-specific terminology accurately. If a question says 'discuss', consider more than one dimension; if it says 'evaluate', weigh evidence and provide a reasoned judgement."},
      {heading:"Maps, diagrams and data",body:"Read legends, scale, axis units, sample descriptions and time periods before interpreting a figure. State a pattern supported by the data and explain plausible mechanisms while avoiding unsupported causation. In psychology or sociology, sample size, selection and operational definitions may limit generalisation. In history, image sources reflect perspective; in political science, a constitutional text or institutional chart must be interpreted in context."},
      {heading:"Revision and source discipline",body:"Build revision sheets with definition, key thinkers/terms where prescribed, arguments, evidence/examples, critiques or limitations and a one-sentence conclusion. Confirm the exact session's chapter list and case-study scope from CBSE's current syllabus. Never invent quotations, studies, statistics or citations to make an answer sound authoritative."}
    ],
    ["Long response: definition → context → explanation → evidence/case → consequence/critique → conclusion","Comparison: same dimensions applied to each case","Data response: describe pattern → compare values → explain within evidence limits"],
    [
      {title:"Prepare a 5-mark conceptual response",steps:["Write the core definition in one sentence.","Develop three distinct points, each with a short explanation/example.","Include a limitation or second perspective if the command word asks for discussion/evaluation.","Conclude by answering the question directly."]},
      {title:"Interpret a source/graph",steps:["Read title, author/date, axis units, legend and sample/context.","Describe the observable information before inferring meaning.","Connect the pattern to a prescribed concept or event.","State one limitation where the evidence does not establish a causal claim."]}
    ],
    ["Using a memorised example that does not match the question.","Treating correlation or a small sample as proof of causation.","Defining one concept by merely repeating another term.","Inventing a quote/statistic/source."],
    ["Follow the relevant subject's expected method: chronology for history, spatial scale for geography, institution/power for political science, method/evidence for psychology and sociology."],
    ["Why must a case study be linked to a concept?","How does a balanced evaluation differ from a list?","What can a graph show, and what might it not prove?"],
    ["Operational definition: specific way a concept is measured/observed in a study.","Causation: a mechanism by which a change produces another change.","Perspective: standpoint shaping how a source presents events/ideas."]);

  const all = [g10History,g10Geography,g10Civics,g10Economics,g10English,g10Hindi,g11Accountancy,g11Economics,g11CS,g12Accountancy,g12Economics,g12Business,g12CS,g12Humanities];
  window.KP_HUMANITIES_GUIDES = all;
})();
